(x, y, t) => {
  const cx = 240, cy = 120;
  const n1 = Math.sin(x*0.023+t*0.31)*Math.cos(y*0.019-t*0.27);
  const n2 = Math.cos(x*0.017-t*0.22)*Math.sin(y*0.025+t*0.33);
  const n3 = Math.sin((x+y)*0.013+t*0.4)*Math.cos((x-y)*0.011-t*0.35);
  const wx = n1*18 + n2*12 + Math.sin(t*0.15)*5;
  const wy = n2*18 + n3*12 + Math.cos(t*0.18)*5;
  const sx = x + wx, sy = y + wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*110, 40+Math.cos(t*0.65)*60, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.38+1.5)*70, 200+Math.sin(t*0.52+2)*55, 0.065, 2.4, 1.15]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const wave = Math.sin(d*f - t*sp);
    aS += wave * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    cS += Math.sin(d*f*1.3 - t*sp*0.8 + 2.8) * w * 0.5;
  }
  const tw = 8, aSn=aS/tw, iSn=iS/tw, cSn=cS/tw;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1) + Math.sin(sx*0.02+sy*0.05-t*0.9))/3;
  const micro = (Math.sin(sx*0.18+t*1.2)*Math.sin(sy*0.22-t*0.9) + Math.sin((sx-sy)*0.15+t*1.5)*Math.cos((sx+sy)*0.13-t*1.1))*0.3;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2) + Math.sin(dist*0.03-ang*2+t*0.8))*0.33;
  const radPulse = Math.sin(dist*0.04-t*2)*Math.exp(-dist*0.003);
  const reaction = Math.tanh((aSn - iSn*0.65 + bg*0.25 + spiral*0.4 + cSn*0.3 + micro + radPulse*0.3)*2.0);
  const diffLap = (Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5 + Math.sin(sx*0.08-sy*0.12+t*0.7)*0.4);
  const cell = Math.tanh(diffLap*1.5)*0.3;
  const blend = reaction*0.7 + cell*0.3;
  const v = blend*0.5+0.5;
  const lum = 0.75 + Math.sin(reaction*Math.PI)*0.25;
  const edge = Math.abs(reaction)>0.65 ? 1.0 + (Math.abs(reaction)-0.65)*1.2 : 1.0;
  const glow = Math.max(0, reaction)*0.15;
  const pal = [
    [5,10,45],[10,35,80],[12,70,105],[18,120,130],
    [45,165,140],[130,190,120],[210,195,70],[230,150,55],
    [220,100,60],[190,60,65],[140,35,60],[90,20,55],[45,12,42],[5,10,45]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*180)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*140)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*60)|0)
  ];
}
